  const openRec=(S.rec||[]).filter(r=>!r.paused&&r.b==b&&(r.type=='out'||(r.type=='tr'&&!r.alloc))&&recDue(r,P)&&!S.exp.some(e=>e.rid==r.id&&e.pk==k)).reduce((s,r)=>s+r.a,0);
  const L=S.exp.filter(e=>inP(e,P)&&!isPlan(e)&&!isRecE(e)&&e.b==b&&(e.type=='out'||(e.type=='tr'&&!e.alloc))),var0=L.reduce((s,e)=>s+e.a,0),r7=L.filter(e=>e.t>Date.now()-7*D).reduce((s,e)=>s+e.a,0)/Math.min(7,P.idx);
