  S.exp.forEach(e=>{if(e.type!='out'||e.corr||isPlan(e)||isRecE(e)||isTabu(e.b))return;const k=e.c||'Sonstiges';if(inP(e,P))cur[k]=(cur[k]||0)+e.a;else for(let o=-1;o>=-3;o--){if(inP(e,period(o))){avg[k]=(avg[k]||0)+e.a;break}}});
